class Solution {
public:
    int maxScore(string s) {
        int totalOnes = 0;
        for (char c : s) {
            if (c == '1') totalOnes++;
        }
        int zerosLeft = 0, onesLeft = 0, ans = 0;
        int n = (int)s.size();
        for (int i = 0; i < n - 1; i++) {
            if (s[i] == '0') zerosLeft++;
            else onesLeft++;
            int onesRight = totalOnes - onesLeft;
            if (zerosLeft + onesRight > ans) ans = zerosLeft + onesRight;
        }
        return ans;
    }
};
